---@class OverseaManagePersonnelChargePopup
local OverseaManagePersonnelChargePopup = Class("OverseaManagePersonnelChargePopup")
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
local ConsumeItemPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManagePersonnelChargeConsumeCell"
function OverseaManagePersonnelChargePopup:__init()
    self.consumeItemEnv = {}
    self.consumeData = {}
end

function OverseaManagePersonnelChargePopup:Awake()
    self:AddUIClick()
    self:InitConsumeItem()
    self:InitPowerVo()
end

function OverseaManagePersonnelChargePopup:AddUIClick()
    SetButtonAction(self.BtnClose.gameObject,Bind(self,self.OnBtnCloseClick))
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnBtnChargeClick))
end

function OverseaManagePersonnelChargePopup:InitConsumeItem()
    KTool.SetActive(self.UIFX_active.gameObject,false)
    local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(27)
    self.consumeIds = string.split(vo.num,";")

    if self.ConsumeNode then
        local env = CfUtils.GetLuaScr(self.ConsumeNode,ConsumeItemPath)
        if env then
            env:SetCallBack(Bind(self,self.OnConsumeItemClick),Bind(self,self.IsOverLimitPower))
            self.consumeItemEnv[1] = env
            env:RefreshShow(self.consumeIds[1])
        end
    end

    if #self.consumeIds > 1 then
        for i = 2, #self.consumeIds do
            local consumeGo = CS.UnityEngine.GameObject.Instantiate(self.ConsumeNode.gameObject)
            if consumeGo then
                consumeGo.name = self.ConsumeNode.name..i
                KTool.SetParent(consumeGo,self.CosumeDisplay.gameObject,false)
                local env = CfUtils.GetLuaScr(consumeGo,ConsumeItemPath)
                if env then
                    env:SetCallBack(Bind(self,self.OnConsumeItemClick),Bind(self,self.IsOverLimitPower))
                    env:RefreshShow(self.consumeIds[i])
                    self.consumeItemEnv[i] = env
                end
            end
        end
    end
end

function OverseaManagePersonnelChargePopup:RefreshConsumeItemShow()
    for i = 1, #self.consumeIds do
        local id = self.consumeIds[i]
        self.consumeItemEnv[i]:RefreshShow(id)
    end
end

