function OverseaManagePersonnelChargePopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            if self.parameters and self.parameters.callBack then
                self.parameters.callBack()
            end
            self.parameters = nil
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
