---click start--------------------
function OverseaManagePersonnelChargePopup:OnBtnCloseClick()
    UIModule.CloseDialog(self.controller)
end

function OverseaManagePersonnelChargePopup:OnBtnChargeClick()
    if self.consumeData and next(self.consumeData) then
        local json = table.serialize(self.consumeData)
        GameUtils.Request(Interfaces.MaidCoffeeCharge,{goods = json},function(request,response)
            if checkInt(response.errCode) == 0 then
                local data = {}
                for i, v in pairs(self.consumeData) do
                    table.insert(data,{goodsId = i,num = v})
                end
                GoodsUtils.ConsumeGoods(data)
                local responseData = response.data
                local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
                if maidCoffeeHomeDojo then
                    maidCoffeeHomeDojo:UpdateCatElectric(checkNumber(responseData.catElectric))
                end
                self:RefreshShow()
                self:RefreshConsumeItemShow()
            end
        end)
    end
end

function OverseaManagePersonnelChargePopup:OnConsumeItemClick(id,num)
    self.consumeData[id] = num
    self:RefreshPowerShow()
end

function OverseaManagePersonnelChargePopup:IsOverLimitPower()
    local addPower = self:GetAddPower()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local curPower = maidCoffeeHomeDojo:GetCatElectric() + addPower
    if curPower >= tonumber(self.powerVo.electricity) then
        return true
    end
    return false
end

function OverseaManagePersonnelChargePopup:GetAddPower()
    local addPower = 0
    for i, v in pairs(self.consumeData) do
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(i)
        if goodsVo then
            addPower = addPower + goodsVo.effectNum * v
        end
    end
    return addPower
end

function OverseaManagePersonnelChargePopup:RefreshPowerShow()
    local addPower = self:GetAddPower()
    if addPower > 0 then
        KTool.SetActive(self.UIFX_active.gameObject,true)
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
        local curPower = maidCoffeeHomeDojo:GetCatElectric() + addPower

        local redPercent = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(28).num)
        local redNum = redPercent * tonumber(self.powerVo.electricity)
        local status = (curPower >= redNum) and 1 or 2
        CfUtils.SetUISwitchImage(self.Fill,status)
        self.Slider.value = curPower/self.powerVo.electricity
        CfUtils.FillText(self.PowerNum,addPower)
        CfUtils.FillText(self.ProgressNum,curPower.."/"..self.powerVo.electricity)
    end
end

function OverseaManagePersonnelChargePopup:InitPowerVo()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local maidCoffeeLevel = component:GetCafeLevel()
    self.powerVo = MaidCoffeeUtils.GetMaidCoffeeCatPowerVo(maidCoffeeLevel)
end
